import { NotFoundError } from '../../domain/errors/DomainError';

export async function requireFound<T>(lookup: Promise<T | undefined>, entity: string, id: string): Promise<T> {
  const found = await lookup;
  if (found === undefined) {
    throw new NotFoundError(entity, id);
  }
  return found;
}

